-- WI Club CRM · модуль «Онбординг» · таблицы + шаблон + план Софии (19 окт 2026)
-- Запустить ОДИН раз в Supabase → SQL Editor
begin;
-- Модуль «Онбординг»: таблицы (схема onboarding уже создана)
grant usage on schema onboarding to authenticated, service_role;

create table onboarding.template_weeks (
  key text primary key,
  kind text not null check (kind in ('week','rhythm','school')),
  num int,
  title text not null,
  sort int not null default 0
);

create table onboarding.template_items (
  id uuid primary key default gen_random_uuid(),
  week_key text not null references onboarding.template_weeks(key) on update cascade,
  block text not null default '',
  title text not null,
  action text not null default '',
  doc_type text not null default '',
  owner text not null default 'curator' check (owner in ('curator','marketing','finance')),
  tags text[] not null default '{}',
  link_mode text not null default 'template' check (link_mode in ('template','copy','none')),
  template_url text,
  sort int not null default 0,
  archived boolean not null default false,
  created_at timestamptz not null default now()
);

create table onboarding.onboardings (
  id uuid primary key default gen_random_uuid(),
  candidate_id uuid not null unique references public.franchise_candidates(id) on delete restrict,
  partner_id uuid references public.partners(id) on delete set null,
  city text,
  start_date date,
  curator text,
  call_day text,
  current_week int,
  status text not null default 'onboarding' check (status in ('onboarding','opened')),
  opened_at date,
  drive_folder_url text,
  next_call_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table onboarding.plan_items (
  id uuid primary key default gen_random_uuid(),
  onboarding_id uuid not null references onboarding.onboardings(id) on delete cascade,
  template_item_id uuid references onboarding.template_items(id) on delete set null,
  week_key text not null,
  block text not null default '',
  title text not null,
  action text not null default '',
  doc_type text not null default '',
  owner text not null default 'curator' check (owner in ('curator','marketing','finance')),
  tags text[] not null default '{}',
  link_mode text not null default 'template' check (link_mode in ('template','copy','none')),
  template_url text,
  file_url text,
  status text not null default 'todo' check (status in ('todo','progress','done','moved')),
  done_date date,
  custom boolean not null default false,
  hidden boolean not null default false,
  sort int not null default 0,
  updated_at timestamptz not null default now()
);
create index on onboarding.plan_items(onboarding_id);

create table onboarding.milestones (
  id uuid primary key default gen_random_uuid(),
  onboarding_id uuid not null references onboarding.onboardings(id) on delete cascade,
  date date,
  title text not null,
  is_key boolean not null default false,
  sort int not null default 0
);
create index on onboarding.milestones(onboarding_id);

create table onboarding.meetings (
  id uuid primary key default gen_random_uuid(),
  onboarding_id uuid not null references onboarding.onboardings(id) on delete cascade,
  held_on date not null,
  week int,
  participants text,
  done_items text[] not null default '{}',
  notes text[] not null default '{}',
  numbers jsonb not null default '[]',
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index on onboarding.meetings(onboarding_id);

create table onboarding.tasks (
  id uuid primary key default gen_random_uuid(),
  onboarding_id uuid not null references onboarding.onboardings(id) on delete cascade,
  meeting_id uuid references onboarding.meetings(id) on delete set null,
  title text not null,
  assignee text not null default '',
  assignee_kind text not null default 'partner' check (assignee_kind in ('partner','hq')),
  due date,
  done boolean not null default false,
  created_at timestamptz not null default now()
);
create index on onboarding.tasks(onboarding_id);

-- чтение через RLS; запись только service_role (серверные действия после проверки роли)
grant select on all tables in schema onboarding to authenticated;
grant all on all tables in schema onboarding to service_role;

alter table onboarding.template_weeks enable row level security;
alter table onboarding.template_items enable row level security;
alter table onboarding.onboardings enable row level security;
alter table onboarding.plan_items enable row level security;
alter table onboarding.milestones enable row level security;
alter table onboarding.meetings enable row level security;
alter table onboarding.tasks enable row level security;

create policy tpl_weeks_read on onboarding.template_weeks for select to authenticated
  using (public.can_view_network() or (select public.current_partner_id()) is not null);
create policy tpl_items_read on onboarding.template_items for select to authenticated
  using (public.can_view_network() or (select public.current_partner_id()) is not null);
create policy onb_read on onboarding.onboardings for select to authenticated
  using (public.can_view_network() or partner_id = (select public.current_partner_id()));
create policy plan_read on onboarding.plan_items for select to authenticated
  using (exists (select 1 from onboarding.onboardings o where o.id = onboarding_id
    and (public.can_view_network() or o.partner_id = (select public.current_partner_id()))));
create policy miles_read on onboarding.milestones for select to authenticated
  using (exists (select 1 from onboarding.onboardings o where o.id = onboarding_id
    and (public.can_view_network() or o.partner_id = (select public.current_partner_id()))));
create policy meet_read on onboarding.meetings for select to authenticated
  using (exists (select 1 from onboarding.onboardings o where o.id = onboarding_id
    and (public.can_view_network() or o.partner_id = (select public.current_partner_id()))));
create policy tasks_read on onboarding.tasks for select to authenticated
  using (exists (select 1 from onboarding.onboardings o where o.id = onboarding_id
    and (public.can_view_network() or o.partner_id = (select public.current_partner_id()))));
do $$ begin if exists (select 1 from onboarding.template_items) then raise exception 'Шаблон онбординга уже загружен, повторно запускать не нужно'; end if; end $$;
-- Шаблон онбординга УК (эталон, из «WiClub_София_Онбординг»)

-- Онбординг Софии (Елена Георгиева), план со статусами из таблицы
