 values ('b00e17c4-c616-42ea-bfc2-a3e02428262c','fa4daffd-2751-4506-9163-727c99474b6a','София · Болгария','2026-06-10','Анастасия','по четвергам',10,'onboarding')
 on conflict (candidate_id) do nothing returning id)
select 1 from o;
commit;
notify pgrst, 'reload schema';
